<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, imageUrl, type FileSummary, type PageSummary, type ProcessingInfo } from '../api'
import { toast } from '../toast'
import PreviewModal from '../components/PreviewModal.vue'
import AppDialog from '../components/AppDialog.vue'
import AppendPagesModal from '../components/AppendPagesModal.vue'
import DuplicateReview from '../components/DuplicateReview.vue'
const router=useRouter(),fileId=Number(useRoute().params.id)
const file=ref<FileSummary|null>(null),pages=ref<PageSummary[]>([]),total=ref(0),pageNo=ref(1),pageSize=24
const editing=ref(false),editName=ref(''),editCategory=ref(''),editTags=ref(''),editSource=ref('')
const selected=ref(new Set<number>()),management=ref<ProcessingInfo|null>(null),revision=ref(0)
const appendOpen=ref(false),deleteOpen=ref(false),busy=ref(false),showDuplicates=ref(false)
const preview=ref<{pageId:number;title:string}|null>(null),loadError=ref('')
const processing=computed(()=>['parsing','embedding','appending','enriching'].includes(file.value?.status||''))
let timer:ReturnType<typeof setInterval>|null=null
function statusLabel(s:string){return ({ready:'已完成',ready_limited:'部分处理未完成',parsing:'解析中',embedding:'向量化中',appending:'追加页面中',enriching:'生成标签 / 相似检测',failed:'处理失败'} as Record<string,string>)[s]||s}
async function loadFile(){file.value=await api.getFile(fileId);if(!editing.value){editName.value=file.value.name;editCategory.value=file.value.category;editTags.value=file.value.tags;editSource.value=file.value.source}}
async function loadPages(){const r=await api.listPages({file_id:fileId,page:pageNo.value,page_size:pageSize});pages.value=r.items;total.value=r.total}
async function loadManagement(){management.value=(await api.management()).files[fileId]||null}
async function changed(){try{selected.value=new Set();await Promise.all([loadFile(),loadPages(),loadManagement()]);revision.value++;loadError.value=''}catch(e:any){loadError.value=e.message;toast(e.message,'error')}}
async function refresh(){if(processing.value){try{await Promise.all([loadFile(),loadManagement()]);if(!processing.value){await loadPages();revision.value++;if(management.value?.pending_count){showDuplicates.value=true;toast(`发现 ${management.value.pending_count} 组相似页面，请核对后处理`)}}}catch{}}}
function toggle(id:number){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
async function deletePages(){busy.value=true;try{await api.deletePages(fileId,[...selected.value]);deleteOpen.value=false;toast('页面已删除，下载内容已同步更新');pageNo.value=1;await changed()}catch(e:any){toast(e.message,'error')}finally{busy.value=false}}
async function retryProcessing(){busy.value=true;try{await api.retryProcessing(fileId);toast('已开始处理');await loadFile();await loadManagement()}catch(e:any){toast(e.message,'error')}finally{busy.value=false}}
async function saveEdit(){try{file.value=await api.updateFile(fileId,{name:editName.value,category:editCategory.value,tags:editTags.value,source:editSource.value});editing.value=false;toast('已保存')}catch(e:any){toast(e.message,'error')}}
async function remove(){if(!confirm(`确认删除「${file.value?.name}」及其全部页面？`))return;try{await api.deleteFile(fileId);toast('已删除');router.push('/library')}catch(e:any){toast(e.message,'error')}}
async function turnPage(delta:number){pageNo.value+=delta;try{await loadPages()}catch(e:any){toast(e.message,'error')}}
onMounted(()=>{changed();timer=setInterval(refresh,5000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
  <div v-if="file" class="detail-view">
    <button class="back-link" @click="router.push('/library')">← 返回素材库</button>
    <header class="detail-head"><div><h2>{{file.name}}</h2><div class="detail-meta"><span class="badge" :class="file.status">{{statusLabel(file.status)}}</span><span>{{file.page_count}} 页</span><span>{{file.category}}</span></div><p v-if="file.error_message" class="error">{{file.error_message}}</p></div><div class="actions"><button class="btn btn-sm" @click="editing=!editing">{{editing?'取消编辑':'编辑信息'}}</button><a class="btn btn-sm" :href="api.downloadUrl(file.id)">下载当前页面</a><button class="btn btn-sm" :disabled="processing||busy" @click="remove">删除文件</button></div></header>
    <section v-if="editing" class="edit-panel"><div class="edit-grid"><label>文件名<input v-model="editName" class="text-input"></label><label>分类<input v-model="editCategory" class="text-input"></label><label>来源<input v-model="editSource" class="text-input"></label><label>文件标签<input v-model="editTags" class="text-input" placeholder="逗号分隔"></label></div><button class="btn primary btn-sm" @click="saveEdit">保存</button></section>
    <section class="management-bar"><div><strong>页面标签与相似检测</strong><p v-if="processing">{{statusLabel(file.status)}}，完成后自动刷新。<span v-if="management?.total_pages"> 标签 {{management.tagged_pages}} / {{management.total_pages}} 页</span></p><p v-else-if="management?.error_message" class="error">{{management.error_message}}</p><p v-else-if="!management">新上传页面会自动生成标签；现有页面可手动生成，不会扫描存量重复。</p><p v-else>{{management.tag_status==='done'?'标签已生成':'标签未全部就绪'}} · {{management.duplicate_status==='done'?'相似检测已完成':management.duplicate_status==='skipped'?'存量页面不做重复检测':'等待全部页面向量就绪后检测'}}</p></div><div class="actions"><button v-if="!management||management.tag_status!=='done'||!['done','skipped'].includes(management.duplicate_status)" class="btn btn-sm" :disabled="processing||busy" @click="retryProcessing">{{management?'重试未完成项':'生成页面标签'}}</button><button class="btn btn-sm" :class="{primary:management?.pending_count}" @click="showDuplicates=!showDuplicates">相似检测{{management?.pending_count?` · ${management.pending_count} 组`:''}}</button></div></section>
    <DuplicateReview v-if="showDuplicates" :file-id="fileId" :revision="revision" @changed="changed"/>
    <div class="page-toolbar"><h3>页面素材 <span>共 {{total}} 页</span></h3><div class="actions"><button class="btn btn-sm" :disabled="processing||busy||!pages.length" @click="selected=new Set(pages.map(p=>p.id))">选择本页</button><button v-if="selected.size" class="btn btn-sm" @click="selected=new Set()">取消选择</button><button class="btn btn-sm" :disabled="processing||busy||!selected.size" @click="deleteOpen=true">删除选中{{selected.size?` (${selected.size})`:''}}</button><button class="btn primary btn-sm" :disabled="processing||busy" @click="appendOpen=true">＋ 追加页面</button></div></div>
    <p v-if="!total&&!processing" class="quiet">当前文件没有页面，可以追加新的 PPTX 页面。</p>
    <div class="page-grid"><article v-for="p in pages" :key="p.id" class="page-item"><div class="page-thumb" :class="{selected:selected.has(p.id)}"><input class="page-check" type="checkbox" :checked="selected.has(p.id)" :disabled="processing||busy" :aria-label="`选择第 ${p.page_no} 页`" @change="toggle(p.id)"><button class="preview-button" :aria-label="`预览：${p.title}`" @click="preview={pageId:p.id,title:p.title}"><img :src="imageUrl(p.id)" loading="lazy" :alt="p.title"></button><span class="pno">第 {{p.page_no}} 页</span></div><p class="ptitle" :title="p.title">{{p.title||`第 ${p.page_no} 页`}}</p><div class="page-tags"><span v-for="tag in p.tags.split(',').filter(Boolean)" :key="tag">{{tag}}</span><span v-if="!p.tags" class="no-tag">{{processing?'标签生成中':'暂无标签'}}</span></div></article></div>
    <div v-if="total>pageSize" class="pager"><button class="btn btn-sm" :disabled="pageNo<=1" @click="turnPage(-1)">上一页</button><span>{{pageNo}} / {{Math.ceil(total/pageSize)}}</span><button class="btn btn-sm" :disabled="pageNo>=Math.ceil(total/pageSize)" @click="turnPage(1)">下一页</button></div>
    <AppendPagesModal v-if="appendOpen" :file-id="fileId" @close="appendOpen=false" @uploaded="changed"/>
    <AppDialog v-if="deleteOpen" title="删除所选页面" @close="!busy&&(deleteOpen=false)"><div class="delete-copy">将删除所选的 {{selected.size}} 页。搜索结果和文件下载会同步更新，其余页面将保持原有顺序。<p>此操作无法在界面中撤销，请确认选择无误。</p></div><template #footer><button class="btn" :disabled="busy" @click="deleteOpen=false">取消</button><button class="btn primary" :disabled="busy" @click="deletePages">{{busy?'正在删除…':'确认删除'}}</button></template></AppDialog>
    <PreviewModal v-if="preview" :page-id="preview.pageId" :title="preview.title" @close="preview=null"/>
  </div>
  <div v-else class="empty-state"><p>{{loadError||'加载中…'}}</p><button v-if="loadError" class="btn" @click="changed">重试</button></div>
</template>
<style scoped>
.back-link{border:0;background:none;color:var(--ink-soft);cursor:pointer;margin-bottom:24px}.detail-head{display:flex;justify-content:space-between;gap:24px;align-items:start;margin-bottom:28px}.detail-head h2{font-size:24px;line-height:1.5;word-break:break-all}.detail-meta{display:flex;gap:14px;align-items:center;margin-top:12px;font-size:13px;color:var(--ink-faint)}.actions{display:flex;gap:8px;flex-wrap:wrap}.error{color:var(--danger)!important;font-size:13px;line-height:1.7;margin-top:10px}.management-bar{padding:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:28px}.management-bar strong{font-size:14px;font-weight:500}.management-bar p{font-size:12px;color:var(--ink-faint);line-height:1.8;margin-top:7px}.page-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.page-toolbar h3{font-size:19px}.page-toolbar h3 span{font:12px var(--sans);color:var(--ink-faint);margin-left:8px}.page-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:26px 22px}.page-thumb{position:relative;border:1px solid var(--line);border-radius:7px;overflow:hidden;background:var(--white)}.preview-button{display:block;border:0;background:none;width:100%;aspect-ratio:16/10;cursor:pointer;padding:0}.preview-button img{width:100%;height:100%;object-fit:contain}.page-check{position:absolute;z-index:2;left:10px;top:10px;width:24px;height:24px;accent-color:var(--brand);cursor:pointer}.page-thumb.selected{outline:2px solid var(--brand);outline-offset:2px}.pno{position:absolute;right:8px;bottom:8px;background:#fffffff0;border:1px solid var(--line);border-radius:4px;padding:3px 6px;font-size:11px;color:var(--ink-soft);pointer-events:none}.ptitle{font-size:13px;color:var(--ink);margin-top:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.page-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.page-tags span{font-size:11px;color:var(--ink-soft);background:var(--bg-deep);padding:3px 7px;border-radius:4px}.page-tags .no-tag{background:none;color:var(--ink-faint)}.delete-copy{padding:24px;line-height:1.9}.delete-copy p,.quiet{color:var(--ink-faint);margin-top:14px;font-size:13px}.pager{display:flex;justify-content:center;gap:20px;align-items:center;margin-top:30px;font-size:13px}.edit-panel{padding:24px;background:var(--white);border:1px solid var(--line);margin-bottom:24px}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.edit-grid label{display:grid;gap:8px;font-size:13px}@media(max-width:750px){.management-bar,.page-toolbar,.detail-head{flex-direction:column;align-items:stretch}.edit-grid{grid-template-columns:1fr}}
</style>
